-- Icon search: a search box and a category filter for Blizzard's icon
-- pickers (new/edit macro, equipment set, guild bank tab).
--
-- The pickers (IconSelectorPopupFrameTemplate) list every icon in the game
-- as bare file IDs, so there is nothing to search by in-game. Data/IconData.lua
-- (generated by scripts/build-icon-data.py from the client's data tables)
-- gives each icon its file name, the spells and items that use it, the
-- classes and professions whose spells use it, and the item types. The
-- spells in your spellbook are added at runtime.
--
-- How it filters: while a search or category is set, the module builds its
-- own list of the matching icons (read from the picker's icon data
-- provider, which it never changes) and points the picker's grid at it.
-- Blizzard picks the highlighted cell by an icon's index in its full list,
-- so post-hooks move the highlight to the icon's index in the filtered one.
-- Picking and Okay only use the icon itself, so they stay Blizzard's. The
-- filter is cleared whenever the picker closes, and the picker's next show
-- points the grid back at Blizzard's own list.
local _, ns = ...

local M = {
    name = "iconsearch",
    title = "Icon Search",
    group = "general",
    description = "Adds a search box and a category filter (class, profession, item type) to the macro, equipment set and guild bank icon pickers.",
    defaults = {
        enabled = true,
        tooltips = true,   -- show what an icon is when hovering it in the picker
    },
}

-- Picker frames to extend, by name. Some come from load-on-demand addons, so
-- they are looked for again after every ADDON_LOADED.
local POPUPS = { "MacroPopupFrame", "GearManagerPopupFrame", "GuildBankPopupFrame" }

local QUESTION_MARK = 134400   -- the "?" icon, always first in the list
local ROW_HEIGHT = 32          -- the filter row pushes the grid down this much

-------------------------------------------------------------------------------
-- Icon data: parsed on first use
-------------------------------------------------------------------------------
local data          -- fileID -> { line, hay, tags } (see Parse)
local byName        -- lower-case file name -> fileID
local tagLabels     -- tag code -> label, e.g. c8 -> Mage, i2_7 -> One-Handed Swords
local mySpells      -- fileID -> lower-case spellbook names, refreshed per search session

local function Parse()
    if data then return end
    local src = ns.IconData
    data, byName, tagLabels = {}, {}, {}
    if not src then return end

    for id, name in pairs(src.classes) do tagLabels["c" .. id] = name end
    for _, p in ipairs(src.professions) do tagLabels["p" .. p[1]] = p[2] end
    for _, class in ipairs(src.itemClasses) do
        for _, sub in ipairs(class[3]) do
            -- Both names, so "weapon" and "swords" both find a sword.
            tagLabels["i" .. class[1] .. "_" .. sub[1]] = class[2] .. " " .. sub[2]
        end
    end

    for line in src.icons:gmatch("[^\n]+") do
        local id, file, tags, rest = line:match("^(%d+)|([^|]*)|([^|]*)|(.*)$")
        id = tonumber(id)
        if id then
            local hay = { file, rest }
            for tag in tags:gmatch("[^,]+") do
                hay[#hay + 1] = tagLabels[tag]
            end
            data[id] = {
                line = line,
                hay = table.concat(hay, "|"):lower():gsub("_", " "),
                tags = "," .. tags .. ",",
            }
            byName[file:lower()] = id
        end
    end
    src.icons = nil   -- parsed: the big string isn't needed any more
end

-- An icon from a provider is a file ID, or a path/file name for the few
-- "loose" icons. Returns the data record (or nil) and the file ID.
local function Lookup(icon)
    if type(icon) == "number" then return data[icon], icon end
    if type(icon) == "string" then
        local id = tonumber(icon)
        if id then return data[id], id end
        local name = icon:match("([^\\/]+)$") or icon
        name = name:gsub("%.%w+$", ""):lower()
        id = byName[name]
        if id then return data[id], id end
        return nil, nil, name
    end
end

-- The player's spellbook: icon -> names. Covers spells the generated data
-- doesn't name, and backs the "My spells" category.
local function CollectMySpells()
    mySpells = {}
    local function Add(icon, name)
        if not icon then return end
        mySpells[icon] = (mySpells[icon] and (mySpells[icon] .. "|") or "") .. (name or ""):lower()
    end
    if C_SpellBook and C_SpellBook.GetNumSpellBookSkillLines and Enum.SpellBookSpellBank then
        local bank = Enum.SpellBookSpellBank.Player
        local future = Enum.SpellBookItemType and Enum.SpellBookItemType.FutureSpell
        for line = 1, C_SpellBook.GetNumSpellBookSkillLines() do
            local info = C_SpellBook.GetSpellBookSkillLineInfo(line)
            if info then
                for i = info.itemIndexOffset + 1, info.itemIndexOffset + info.numSpellBookItems do
                    local kind = C_SpellBook.GetSpellBookItemType(i, bank)
                    if kind ~= "FUTURESPELL" and kind ~= future then
                        Add(C_SpellBook.GetSpellBookItemTexture(i, bank), C_SpellBook.GetSpellBookItemName(i, bank))
                    end
                end
            end
        end
    elseif GetNumSpellTabs then
        for tab = 1, GetNumSpellTabs() do
            local _, _, offset, count = GetSpellTabInfo(tab)
            for i = offset + 1, offset + count do
                Add(GetSpellTexture(i, BOOKTYPE_SPELL), GetSpellBookItemName(i, BOOKTYPE_SPELL))
            end
        end
    end
end

-------------------------------------------------------------------------------
-- Matching
-------------------------------------------------------------------------------
-- Category values: "all", "mine", "c<classID>", "p<skillLine>",
-- "i<itemClass>_" (any subtype) or "i<itemClass>_<subclass>".
local function MatchesCategory(rec, fileID, category)
    if category == "all" then return true end
    if category == "mine" then return fileID ~= nil and mySpells[fileID] ~= nil end
    if not rec then return false end
    if category:sub(-1) == "_" then
        return rec.tags:find("," .. category, 1, true) ~= nil
    end
    return rec.tags:find("," .. category .. ",", 1, true) ~= nil
end

local function MatchesWords(words, rec, fileID, looseName)
    if #words == 0 then return true end
    local hay = rec and rec.hay or looseName or ""
    local mine = fileID and mySpells[fileID]
    local idText = fileID and tostring(fileID)
    for _, word in ipairs(words) do
        if not (hay:find(word, 1, true) or (mine and mine:find(word, 1, true)) or idText == word) then
            return false
        end
    end
    return true
end

local function SplitWords(text)
    local words = {}
    for word in (text or ""):lower():gsub("_", " "):gmatch("%S+") do
        words[#words + 1] = word
    end
    return words
end

-------------------------------------------------------------------------------
-- Filtering
-------------------------------------------------------------------------------
-- popup -> its filter state
local states = {}

-- Do two icons name the same file? A provider lists a few "loose" icons by
-- path, while a texture reports its file ID.
local function SameIcon(a, b)
    if a == b then return true end
    local _, idA = Lookup(a)
    local _, idB = Lookup(b)
    return idA ~= nil and idA == idB
end

-- Index of an icon in the filtered list (the "?" is always 1).
local function IndexIn(list, icon)
    if icon == QUESTION_MARK then return 1 end
    for i = 1, #list do
        if list[i] == icon then return i end
    end
    for i = 1, #list do
        if type(list[i]) == "string" and SameIcon(list[i], icon) then return i end
    end
end

-- Blizzard picks the highlighted grid cell by the icon's index in its own,
-- unfiltered list. While filtering, move it to the icon's index in ours.
local function Reselect(state)
    local list = state.list
    if not list then return end
    local popup = state.popup
    local texture = popup.BorderBox.SelectedIconArea.SelectedIconButton:GetIconTexture()
    popup.IconSelector:SetSelectedIndex(IndexIn(list, texture))
    if popup.SetSelectedIconText then popup:SetSelectedIconText() end
end

-- Rebuild the filtered list for the popup's current provider and filter,
-- then show it. With no filter, hand the grid back to Blizzard's own list.
local function Apply(state, scrollToTop)
    local popup = state.popup
    local provider = popup.iconDataProvider
    if not provider then return end
    local selector = popup.IconSelector
    local words = SplitWords(state.query)

    if #words == 0 and state.category == "all" then
        state.list = nil
        state.count:SetText("")
        if not state.pointed then return end   -- never filtered this time: nothing to undo
        state.pointed = nil
        selector:SetSelectionsDataProvider(
            function(index) return provider:GetIconByIndex(index) end,
            function() return provider:GetNumIcons() end)
        if popup.ReevaluateSelectedIcon then popup:ReevaluateSelectedIcon() end
    else
        Parse()
        if not mySpells then CollectMySpells() end
        local list, seen = {}, {}
        list[1] = provider:GetIconByIndex(1)   -- "?" stays first
        for i = 2, provider:GetNumIcons() do
            local icon = provider:GetIconByIndex(i)
            if icon and not seen[icon] then
                seen[icon] = true
                local rec, fileID, looseName = Lookup(icon)
                if MatchesCategory(rec, fileID, state.category) and MatchesWords(words, rec, fileID, looseName) then
                    list[#list + 1] = icon
                end
            end
        end
        state.list = list
        state.count:SetFormattedText("%d |4icon:icons;", #list - 1)
        state.pointed = true
        selector:SetSelectionsDataProvider(
            function(index) return list[index] end,
            function() return #list end)
        Reselect(state)
    end
    if scrollToTop and selector.ScrollBox and selector.ScrollBox.ScrollToBegin then
        selector.ScrollBox:ScrollToBegin()
    end
end

local function Reset(state)
    state.query, state.category = "", "all"
    state.list, state.pointed = nil, nil
    mySpells = nil
    if state.search then state.search:SetText("") end
    if state.count then state.count:SetText("") end
    if state.dropdown and state.dropdown.GenerateMenu then state.dropdown:GenerateMenu() end
end

-------------------------------------------------------------------------------
-- Tooltip on the grid's icons
-------------------------------------------------------------------------------
local function ShowIconTooltip(button)
    if not (M.db.enabled and M.db.tooltips and button.GetSelection) then return end
    Parse()
    local icon = button:GetSelection()
    if not icon then return end
    local rec, fileID, looseName = Lookup(icon)
    GameTooltip:SetOwner(button, "ANCHOR_RIGHT")
    if not rec then
        GameTooltip:SetText(looseName or (fileID and tostring(fileID)) or "?", 1, 1, 1)
    else
        local _, file, tags, spells, items = strsplit("|", rec.line)
        GameTooltip:SetText(file, 1, 1, 1)
        local classes, kinds = {}, {}
        for tag in tags:gmatch("[^,]+") do
            local kind = tag:sub(1, 1)
            if kind == "c" or kind == "p" then
                classes[#classes + 1] = tagLabels[tag]
            elseif kind == "i" then
                kinds[#kinds + 1] = tagLabels[tag]
            end
        end
        local function Line(label, text)
            if text and text ~= "" then
                GameTooltip:AddLine("|cff99ccff" .. label .. ":|r " .. text, 1, 1, 1, true)
            end
        end
        Line("Spells", (spells or ""):gsub(";", ", "))
        Line("Items", (items or ""):gsub(";", ", "))
        Line("Used by", table.concat(classes, ", "))
        Line("Item types", table.concat(kinds, ", "))
    end
    if fileID then GameTooltip:AddLine("File ID " .. fileID, 0.5, 0.5, 0.5) end
    GameTooltip:Show()
end

-------------------------------------------------------------------------------
-- The filter row
-------------------------------------------------------------------------------
local function BuildMenu(state)
    local src = ns.IconData
    local function IsSelected(value) return state.category == value end
    local function Select(value)
        state.category = value
        Apply(state, true)
    end

    state.dropdown:SetupMenu(function(_, root)
        root:CreateRadio("All categories", IsSelected, Select, "all")
        root:CreateRadio("My spells", IsSelected, Select, "mine")
        if not src then return end

        local _, _, myClass = UnitClass("player")
        if myClass and src.classes[myClass] then
            root:CreateRadio("My class (" .. src.classes[myClass] .. ")", IsSelected, Select, "c" .. myClass)
        end
        local classMenu = root:CreateButton("Class")
        local ids = {}
        for id in pairs(src.classes) do ids[#ids + 1] = id end
        table.sort(ids, function(a, b) return src.classes[a] < src.classes[b] end)
        for _, id in ipairs(ids) do
            classMenu:CreateRadio(src.classes[id], IsSelected, Select, "c" .. id)
        end

        local profMenu = root:CreateButton("Profession")
        for _, p in ipairs(src.professions) do
            profMenu:CreateRadio(p[2], IsSelected, Select, "p" .. p[1])
        end

        local itemMenu = root:CreateButton("Item type")
        for _, class in ipairs(src.itemClasses) do
            local subs = class[3]
            if #subs == 1 then
                itemMenu:CreateRadio(class[2], IsSelected, Select, "i" .. class[1] .. "_")
            else
                local classMenuItem = itemMenu:CreateButton(class[2])
                classMenuItem:CreateRadio("All " .. class[2], IsSelected, Select, "i" .. class[1] .. "_")
                for _, sub in ipairs(subs) do
                    classMenuItem:CreateRadio(sub[2], IsSelected, Select, "i" .. class[1] .. "_" .. sub[1])
                end
            end
        end
    end)
end

-- Show or hide the row and make room for it above the grid.
local function SetRowShown(state, shown)
    local popup = state.popup
    local selector = popup.IconSelector
    shown = shown and M.db.enabled
    state.row:SetShown(shown and selector:IsShown())
    if state.laidOut == shown then return end
    state.laidOut = shown
    local point, rel, relPoint, x, y = unpack(state.selectorPoint)
    selector:ClearAllPoints()
    selector:SetPoint(point, rel, relPoint, x, y - (shown and ROW_HEIGHT or 0))
    popup:SetHeight(state.height + (shown and ROW_HEIGHT or 0))
end

local function Attach(popup)
    if states[popup] or not (popup.IconSelector and popup.BorderBox) then return end
    local state = { popup = popup, query = "", category = "all" }
    states[popup] = state
    state.height = popup:GetHeight()
    state.selectorPoint = { popup.IconSelector:GetPoint(1) }

    local row = CreateFrame("Frame", nil, popup.BorderBox)
    row:SetHeight(24)
    row:SetPoint("TOPLEFT", popup.IconSelector, "TOPLEFT", 4, ROW_HEIGHT - 2)
    row:SetPoint("RIGHT", popup.BorderBox, "RIGHT", -44, 0)
    state.row = row

    local search = CreateFrame("EditBox", nil, row, "SearchBoxTemplate")
    search:SetSize(200, 20)
    search:SetPoint("LEFT", 6, 0)
    search:SetAutoFocus(false)
    if search.Instructions then search.Instructions:SetText("Search icons, spells, items") end
    search:HookScript("OnTextChanged", function(self, userInput)
        state.query = self:GetText()
        if state.timer then state.timer:Cancel() end
        -- A short pause, so typing a word filters once.
        state.timer = C_Timer.NewTimer(userInput and 0.15 or 0, function()
            state.timer = nil
            if popup:IsShown() then Apply(state, true) end
        end)
    end)
    search:SetScript("OnEnterPressed", EditBox_ClearFocus)
    state.search = search

    local count = row:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    count:SetPoint("LEFT", search, "RIGHT", 8, 0)
    state.count = count

    local dropdown = CreateFrame("DropdownButton", nil, row, "WowStyle1DropdownTemplate")
    dropdown:SetWidth(150)
    dropdown:SetPoint("RIGHT", row, "RIGHT", 0, 0)
    if dropdown.SetDefaultText then dropdown:SetDefaultText("All categories") end
    state.dropdown = dropdown
    BuildMenu(state)

    -- Refilter whenever Blizzard rebuilds or re-types the list.
    hooksecurefunc(popup, "Update", function()
        if state.list then Apply(state, false) end
    end)
    if popup.SetIconFilterInternal then
        hooksecurefunc(popup, "SetIconFilterInternal", function()
            if state.list then Apply(state, true) end
        end)
    end
    -- Blizzard re-picks the highlighted cell from its own list here.
    if popup.ReevaluateSelectedIcon then
        hooksecurefunc(popup, "ReevaluateSelectedIcon", function() Reselect(state) end)
    end
    -- Runs on every mouse-up over the picker, but only changes the selection
    -- when an icon was dropped on it: then fix the highlight and scroll to it.
    if popup.SetIconFromMouse then
        hooksecurefunc(popup, "SetIconFromMouse", function()
            local list = state.list
            if not list then return end
            local selector = popup.IconSelector
            local selected = selector:GetSelectedIndex()
            local texture = popup.BorderBox.SelectedIconArea.SelectedIconButton:GetIconTexture()
            if selected and list[selected] and SameIcon(list[selected], texture) then return end
            Reselect(state)
            if selector:GetSelectedIndex() then selector:ScrollToSelectedIndex() end
        end)
    end
    -- Blizzard hides the grid while an icon is dragged onto the picker.
    if popup.UpdateStateFromCursorType then
        hooksecurefunc(popup, "UpdateStateFromCursorType", function()
            SetRowShown(state, true)
        end)
    end
    popup:HookScript("OnShow", function() SetRowShown(state, true) end)
    popup:HookScript("OnHide", function() Reset(state) end)

    -- Details on hover, for the grid's buttons as the scroll box makes them.
    local scrollBox = popup.IconSelector.ScrollBox
    if scrollBox and ScrollUtil and ScrollUtil.AddAcquiredFrameCallback then
        local hooked = {}
        local function HookButton(button)
            if hooked[button] then return end
            hooked[button] = true
            button:HookScript("OnEnter", ShowIconTooltip)
            button:HookScript("OnLeave", GameTooltip_Hide)
        end
        ScrollUtil.AddAcquiredFrameCallback(scrollBox, function(_, button) HookButton(button) end, state)
        -- The grid builds its view on the picker's first show; before that
        -- there are no buttons yet (and ForEachFrame would error).
        if scrollBox.GetView and scrollBox:GetView() then scrollBox:ForEachFrame(HookButton) end
    end

    SetRowShown(state, popup:IsShown())
end

local function AttachAll()
    for _, name in ipairs(POPUPS) do
        local popup = _G[name]
        if popup then Attach(popup) end
    end
end

local frame = CreateFrame("Frame")
frame:SetScript("OnEvent", function()
    if M.db.enabled then AttachAll() end
end)

function M:OnEnable()
    frame:RegisterEvent("ADDON_LOADED")
    AttachAll()
    for _, state in pairs(states) do SetRowShown(state, state.popup:IsShown()) end
end

function M:OnDisable()
    frame:UnregisterEvent("ADDON_LOADED")
    for _, state in pairs(states) do
        state.query, state.category = "", "all"
        if state.popup:IsShown() then Apply(state, true) end   -- back to Blizzard's list
        Reset(state)
        SetRowShown(state, false)
    end
end

function M:BuildOptions(parent, db, y)
    local W = ns.Widgets
    local _
    _, y = W.Checkbox(parent, y, {
        label = "Show icon details on hover",
        tooltip = "Hovering an icon in the picker shows its file name and the spells and items that use it.",
        db = db, key = "tooltips",
    })
    return y
end

ns.RegisterModule(M)
